import { UV } from 'kerium';
import { bindFunctions } from 'utilium';
import { contextOf, createChildContext, defaultContext } from './internal/contexts.js';
import * as fs from './node/index.js';
import { getPromisified, setPromisified } from './node/utils.js';
import * as path from './path.js';
import * as xattr from './vfs/xattr.js';
/**
 * A map of all contexts.
 * @internal
 * @category Contexts
 */
export const boundContexts = new Map();
/**
 * Allows you to restrict operations to a specific root path and set of credentials.
 * Note that the default credentials of a bound context are copied from the global credentials.
 * @category Contexts
 */
export function bindContext(init = {}) {
    const $ = contextOf(this), parent = $.parent || defaultContext;
    if (!fs.statSync.call(parent, parent.root).isDirectory())
        throw UV('ENOTDIR', { syscall: 'chroot', path: parent.root });
    const ctx = createChildContext($, init);
    const boundFS = bindFunctions(fs, ctx);
    boundFS.realpath.native = boundFS.realpath;
    boundFS.realpathSync.native = boundFS.realpathSync;
    for (const [name, value] of Object.entries(fs)) {
        const promisified = getPromisified(value);
        if (promisified)
            setPromisified(boundFS[name], promisified.bind(ctx));
    }
    const bound = Object.assign(ctx, {
        fs: {
            ...boundFS,
            Utf8Stream: fs.Utf8Stream._withContext(ctx),
            promises: bindFunctions(fs.promises, ctx),
            xattr: bindFunctions(xattr, ctx),
        },
        path: bindFunctions(path, ctx),
        bind: (init) => {
            const child = bindContext.call(ctx, init);
            ctx.children.push(child);
            return child;
        },
    });
    boundContexts.set(ctx.id, bound);
    return bound;
}
